/* ========================================
   MedBook — Corporate Landing Page Styles
   ======================================== */

/* CSS Variables */
:root {
  --color-primary: #1B1464;
  --color-primary-light: #2a237a;
  --color-accent: #FFD930;
  --color-accent-hover: #f5cc00;
  --color-white: #FFFFFF;
  --color-gray-50: #F8F9FB;
  --color-gray-100: #F1F3F6;
  --color-gray-200: #E4E7EC;
  --color-gray-300: #D0D5DD;
  --color-gray-400: #98A2B3;
  --color-gray-500: #667085;
  --color-gray-600: #475467;
  --color-gray-700: #344054;
  --color-gray-800: #1D2939;
  --color-gray-900: #101828;
  --color-success: #10B981;
  --color-success-light: #ECFDF5;

  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px rgba(16, 24, 40, 0.05);
  --shadow-md: 0 4px 12px rgba(16, 24, 40, 0.08);
  --shadow-lg: 0 12px 32px rgba(16, 24, 40, 0.12);
  --shadow-xl: 0 24px 48px rgba(16, 24, 40, 0.16);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-700);
  background-color: var(--color-white);
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

img, svg {
  display: block;
  max-width: 100%;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

input {
  font-family: inherit;
  font-size: inherit;
}

/* Container */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 640px) {
  .container {
    padding: 0 32px;
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 48px;
  }
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-weight: 600;
  font-size: 15px;
  line-height: 1.5;
  padding: 12px 24px;
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-primary {
  background-color: var(--color-primary);
  color: var(--color-white);
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
  background-color: var(--color-primary-light);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-primary:active {
  transform: translateY(0);
}

.btn-small {
  padding: 8px 18px;
  font-size: 14px;
}

.btn-app-store,
.btn-google-play {
  background-color: var(--color-gray-900);
  color: var(--color-white);
  padding: 12px 20px;
  font-size: 14px;
  border-radius: var(--radius-md);
}

.btn-app-store:hover,
.btn-google-play:hover {
  background-color: var(--color-gray-800);
  transform: translateY(-1px);
}

/* ========================================
   Header
   ======================================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: rgba(255, 255, 255, 0.92);
  backdrop-filter: saturate(180%) blur(12px);
  -webkit-backdrop-filter: saturate(180%) blur(12px);
  border-bottom: 1px solid var(--color-gray-200);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 20px;
  color: var(--color-primary);
  letter-spacing: -0.02em;
}

.desktop-nav {
  display: none;
  align-items: center;
  gap: 28px;
}

.desktop-nav a {
  font-size: 15px;
  font-weight: 500;
  color: var(--color-gray-600);
  transition: color var(--transition-fast);
}

.desktop-nav a:hover {
  color: var(--color-primary);
}

.desktop-nav .nav-link-secondary {
  color: var(--color-gray-700);
}

@media (min-width: 768px) {
  .desktop-nav {
    display: flex;
  }
}

/* Mobile Menu Toggle */
.mobile-menu-toggle {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 44px;
  height: 44px;
  padding: 10px;
  border-radius: var(--radius-sm);
  transition: background var(--transition-fast);
}

.mobile-menu-toggle:hover {
  background-color: var(--color-gray-100);
}

.mobile-menu-toggle[aria-expanded="true"] .hamburger-bar:nth-child(1) {
  transform: translateY(8px) rotate(45deg);
}

.mobile-menu-toggle[aria-expanded="true"] .hamburger-bar:nth-child(2) {
  opacity: 0;
}

.mobile-menu-toggle[aria-expanded="true"] .hamburger-bar:nth-child(3) {
  transform: translateY(-8px) rotate(-45deg);
}

.hamburger-bar {
  display: block;
  width: 22px;
  height: 2.5px;
  background-color: var(--color-gray-700);
  border-radius: 2px;
  transition: all var(--transition-base);
}

@media (min-width: 768px) {
  .mobile-menu-toggle {
    display: none;
  }
}

/* Mobile Navigation Drawer */
.mobile-nav-overlay {
  position: fixed;
  inset: 0;
  background-color: rgba(16, 24, 40, 0.4);
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-base), visibility var(--transition-base);
  z-index: 110;
}

.mobile-nav-overlay.active {
  opacity: 1;
  visibility: visible;
}

.mobile-nav {
  position: fixed;
  top: 0;
  right: 0;
  width: min(320px, 85vw);
  height: 100vh;
  background-color: var(--color-white);
  box-shadow: var(--shadow-xl);
  transform: translateX(100%);
  transition: transform var(--transition-base);
  z-index: 120;
  display: flex;
  flex-direction: column;
}

.mobile-nav.active {
  transform: translateX(0);
}

.mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  border-bottom: 1px solid var(--color-gray-200);
}

.mobile-nav-close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  color: var(--color-gray-600);
  transition: background var(--transition-fast), color var(--transition-fast);
}

.mobile-nav-close:hover {
  background-color: var(--color-gray-100);
  color: var(--color-gray-900);
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 16px;
}

.mobile-nav-links a {
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  font-size: 16px;
  font-weight: 500;
  color: var(--color-gray-700);
  transition: background var(--transition-fast), color var(--transition-fast);
}

.mobile-nav-links a:hover {
  background-color: var(--color-gray-50);
  color: var(--color-primary);
}

.mobile-nav-links .btn {
  margin-top: 8px;
  justify-content: center;
}

/* ========================================
   Hero Section
   ======================================== */
.hero {
  position: relative;
  background: linear-gradient(135deg, var(--color-primary) 0%, #2d2478 50%, #1B1464 100%);
  padding: 64px 0 120px;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 80%;
  height: 150%;
  background: radial-gradient(ellipse, rgba(255, 217, 48, 0.08) 0%, transparent 70%);
  pointer-events: none;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -10%;
  width: 60%;
  height: 100%;
  background: radial-gradient(ellipse, rgba(255, 255, 255, 0.04) 0%, transparent 70%);
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 720px;
  margin: 0 auto;
}

.hero-title {
  font-size: clamp(32px, 5vw, 52px);
  font-weight: 800;
  line-height: 1.15;
  color: var(--color-white);
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.hero-subtitle {
  font-size: clamp(16px, 2.5vw, 20px);
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.8);
  max-width: 600px;
  margin: 0 auto;
}

/* ========================================
   Search Panel
   ======================================== */
.search-panel {
  position: relative;
  z-index: 2;
  margin-top: -80px;
  padding: 0 0 48px;
}

.search-form {
  display: flex;
  flex-direction: column;
  gap: 0;
  background-color: var(--color-white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
  padding: 8px;
  max-width: 960px;
  margin: 0 auto;
}

@media (min-width: 768px) {
  .search-form {
    flex-direction: row;
    align-items: flex-end;
    gap: 0;
    padding: 12px;
  }
}

.search-field {
  position: relative;
  flex: 1;
  padding: 12px 16px;
}

@media (min-width: 768px) {
  .search-field {
    padding: 8px 16px;
    border-right: 1px solid var(--color-gray-200);
  }

  .search-field:last-of-type {
    border-right: none;
  }
}

.search-label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-gray-500);
  margin-bottom: 6px;
}

.search-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.search-icon {
  position: absolute;
  left: 0;
  color: var(--color-gray-400);
  pointer-events: none;
  flex-shrink: 0;
}

.search-input {
  width: 100%;
  padding: 8px 8px 8px 28px;
  border: none;
  outline: none;
  font-size: 15px;
  color: var(--color-gray-800);
  background: transparent;
}

.search-input::placeholder {
  color: var(--color-gray-400);
}

.location-detect {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  color: var(--color-gray-400);
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background var(--transition-fast);
  flex-shrink: 0;
}

.location-detect:hover {
  color: var(--color-primary);
  background-color: var(--color-gray-50);
}

.chevron-icon {
  position: absolute;
  right: 0;
  color: var(--color-gray-400);
  pointer-events: none;
  flex-shrink: 0;
}

.search-field-insurance .search-input {
  padding-right: 24px;
}

.btn-search {
  padding: 14px 28px;
  font-size: 16px;
  border-radius: var(--radius-lg);
  margin: 8px;
  flex-shrink: 0;
}

@media (min-width: 768px) {
  .btn-search {
    margin: 0;
    border-radius: var(--radius-md);
  }
}

/* Search Suggestions Dropdown */
.search-suggestions {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  background-color: var(--color-white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--color-gray-200);
  max-height: 280px;
  overflow-y: auto;
  z-index: 50;
  padding: 6px;
}

.search-suggestions:not([hidden]) {
  display: block;
}

.search-suggestions li {
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 14px;
  color: var(--color-gray-700);
  transition: background var(--transition-fast);
}

.search-suggestions li:hover,
.search-suggestions li[aria-selected="true"] {
  background-color: var(--color-gray-50);
  color: var(--color-primary);
}

.search-suggestions li strong {
  color: var(--color-gray-900);
  font-weight: 600;
}

/* ========================================
   Specialties Section
   ======================================== */
.specialties {
  padding: 80px 0;
  background-color: var(--color-white);
}

.section-title {
  font-size: clamp(26px, 3.5vw, 34px);
  font-weight: 700;
  color: var(--color-gray-900);
  text-align: center;
  margin-bottom: 48px;
  letter-spacing: -0.02em;
}

.specialties-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

@media (min-width: 640px) {
  .specialties-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
  }
}

@media (min-width: 1024px) {
  .specialties-grid {
    grid-template-columns: repeat(6, 1fr);
    gap: 24px;
  }
}

.specialty-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 28px 16px;
  background-color: var(--color-gray-50);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-gray-200);
  transition: all var(--transition-base);
}

.specialty-card:hover {
  background-color: var(--color-white);
  border-color: var(--color-primary);
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.specialty-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 64px;
  height: 64px;
  border-radius: var(--radius-full);
  background-color: var(--color-primary);
  color: var(--color-accent);
  margin-bottom: 16px;
  transition: transform var(--transition-base);
}

.specialty-card:hover .specialty-icon {
  transform: scale(1.08);
}

.specialty-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--color-gray-900);
  margin-bottom: 6px;
}

.specialty-desc {
  font-size: 13px;
  line-height: 1.5;
  color: var(--color-gray-500);
  display: none;
}

@media (min-width: 640px) {
  .specialty-desc {
    display: block;
  }
}

/* ========================================
   How It Works Section
   ======================================== */
.how-it-works {
  padding: 80px 0;
  background-color: var(--color-gray-50);
}

.steps-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .steps-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 32px;
  }
}

.step-card {
  position: relative;
  background-color: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  border: 1px solid var(--color-gray-200);
  transition: all var(--transition-base);
}

.step-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.step-number {
  position: absolute;
  top: -14px;
  left: 28px;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-accent);
  color: var(--color-primary);
  font-size: 14px;
  font-weight: 800;
  border-radius: var(--radius-full);
  box-shadow: var(--shadow-sm);
}

.step-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background-color: var(--color-primary);
  color: var(--color-accent);
  margin-bottom: 20px;
}

.step-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-gray-900);
  margin-bottom: 10px;
}

.step-desc {
  font-size: 15px;
  line-height: 1.6;
  color: var(--color-gray-500);
}

/* ========================================
   Platform Stats Section
   ======================================== */
.platform-stats {
  padding: 56px 0;
  background: linear-gradient(135deg, var(--color-primary) 0%, #2d2478 100%);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px 24px;
  text-align: center;
}

@media (min-width: 768px) {
  .stats-grid {
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
  }
}

.stat-value {
  font-size: clamp(24px, 3.5vw, 36px);
  font-weight: 800;
  color: var(--color-accent);
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.stat-label {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.75);
  line-height: 1.4;
}

/* ========================================
   Testimonials Section
   ======================================== */
.testimonials {
  padding: 80px 0;
  background-color: var(--color-white);
}

.testimonials-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .testimonials-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
  }
}

.testimonial-card {
  background-color: var(--color-gray-50);
  border-radius: var(--radius-lg);
  padding: 28px;
  border: 1px solid var(--color-gray-200);
  transition: all var(--transition-base);
}

.testimonial-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.testimonial-stars {
  display: flex;
  gap: 4px;
  color: var(--color-accent);
  margin-bottom: 14px;
}

.testimonial-stars svg {
  filter: drop-shadow(0 1px 1px rgba(0,0,0,0.08));
}

.testimonial-quote {
  font-size: 15px;
  line-height: 1.65;
  color: var(--color-gray-700);
  margin-bottom: 18px;
}

.testimonial-author {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.testimonial-name {
  font-weight: 700;
  font-size: 15px;
  color: var(--color-gray-900);
}

.testimonial-location {
  font-size: 13px;
  color: var(--color-gray-500);
}

/* ========================================
   App Promo Section
   ======================================== */
.app-promo {
  padding: 80px 0;
  background-color: var(--color-gray-50);
}

.app-promo-inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: 48px;
  align-items: center;
}

@media (min-width: 768px) {
  .app-promo-inner {
    grid-template-columns: 1fr 1fr;
    gap: 64px;
  }
}

.app-promo-content .section-title {
  text-align: left;
  margin-bottom: 16px;
}

.app-promo-subtitle {
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-600);
  margin-bottom: 24px;
}

.app-promo-features {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 32px;
}

.app-promo-features li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 15px;
  color: var(--color-gray-700);
}

.app-promo-features li svg {
  color: var(--color-success);
  flex-shrink: 0;
}

.app-promo-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

/* Phone Mockup */
.app-promo-visual {
  display: flex;
  justify-content: center;
}

.phone-mockup {
  width: 240px;
  height: 480px;
  background-color: var(--color-gray-900);
  border-radius: 36px;
  padding: 10px;
  box-shadow: var(--shadow-xl);
}

.phone-screen {
  width: 100%;
  height: 100%;
  background: linear-gradient(180deg, var(--color-gray-50) 0%, var(--color-white) 100%);
  border-radius: 28px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.phone-header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 16px 8px;
}

.phone-dot {
  width: 6px;
  height: 6px;
  border-radius: var(--radius-full);
  background-color: var(--color-gray-300);
}

.phone-notch {
  width: 48px;
  height: 16px;
  border-radius: var(--radius-full);
  background-color: var(--color-gray-900);
}

.phone-content {
  flex: 1;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.phone-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  background-color: var(--color-white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
}

.phone-avatar {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-full);
  background: linear-gradient(135deg, var(--color-primary), #4a3fb5);
  flex-shrink: 0;
}

.phone-lines {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

.phone-line {
  height: 8px;
  border-radius: var(--radius-full);
  background-color: var(--color-gray-200);
}

.phone-line.short {
  width: 60%;
}

/* ========================================
   Footer
   ======================================== */
.site-footer {
  background-color: var(--color-gray-900);
  color: var(--color-gray-400);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

@media (min-width: 640px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1.5fr repeat(4, 1fr);
    gap: 32px;
  }
}

.footer-brand .logo {
  color: var(--color-white);
  margin-bottom: 12px;
}

.footer-tagline {
  font-size: 14px;
  line-height: 1.5;
  color: var(--color-gray-500);
  max-width: 240px;
}

.footer-heading {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-white);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}

.footer-links-group ul {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-links-group a {
  font-size: 14px;
  color: var(--color-gray-400);
  transition: color var(--transition-fast);
}

.footer-links-group a:hover {
  color: var(--color-white);
}

.footer-bottom {
  border-top: 1px solid var(--color-gray-800);
  padding-top: 24px;
  text-align: center;
}

.footer-bottom p {
  font-size: 13px;
  color: var(--color-gray-500);
}

/* ========================================
   Accessibility & Utilities
   ======================================== */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Focus styles */
a:focus-visible,
button:focus-visible,
input:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--color-primary);
  color: var(--color-white);
  padding: 8px 16px;
  z-index: 200;
  transition: top var(--transition-fast);
}

.skip-link:focus {
  top: 0;
}

/* Screen reader only */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/**
 * MedBook — Corporate Landing Page Interactions
 */

(function () {
  'use strict';

  // ========================================
  // Mobile Navigation
  // ========================================
  const mobileMenuToggle = document.getElementById('mobileMenuToggle');
  const mobileNav = document.getElementById('mobileNav');
  const mobileNavOverlay = document.getElementById('mobileNavOverlay');
  const mobileNavClose = document.getElementById('mobileNavClose');

  function openMobileNav() {
    mobileMenuToggle.setAttribute('aria-expanded', 'true');
    mobileNav.classList.add('active');
    mobileNavOverlay.classList.add('active');
    mobileNav.setAttribute('aria-hidden', 'false');
    mobileNavOverlay.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
    // Focus first link for accessibility
    const firstLink = mobileNav.querySelector('a');
    if (firstLink) firstLink.focus();
  }

  function closeMobileNav() {
    mobileMenuToggle.setAttribute('aria-expanded', 'false');
    mobileNav.classList.remove('active');
    mobileNavOverlay.classList.remove('active');
    mobileNav.setAttribute('aria-hidden', 'true');
    mobileNavOverlay.setAttribute('aria-hidden', 'true');
    document.body.style.overflow = '';
    mobileMenuToggle.focus();
  }

  if (mobileMenuToggle) {
    mobileMenuToggle.addEventListener('click', openMobileNav);
  }

  if (mobileNavClose) {
    mobileNavClose.addEventListener('click', closeMobileNav);
  }

  if (mobileNavOverlay) {
    mobileNavOverlay.addEventListener('click', closeMobileNav);
  }

  // Close on Escape key
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && mobileNav.classList.contains('active')) {
      closeMobileNav();
    }
  });

  // Close mobile nav when clicking a link
  mobileNav.querySelectorAll('a').forEach(function (link) {
    link.addEventListener('click', function () {
      closeMobileNav();
    });
  });

  // ========================================
  // Search Autocomplete
  // ========================================
  const searchInput = document.getElementById('searchInput');
  const searchSuggestions = document.getElementById('searchSuggestions');

  const suggestionsData = [
    { text: 'Dentist', type: 'Specialty' },
    { text: 'Primary Care', type: 'Specialty' },
    { text: 'Dermatologist', type: 'Specialty' },
    { text: 'Psychiatrist', type: 'Specialty' },
    { text: 'Eye Doctor', type: 'Specialty' },
    { text: 'Orthopedic Surgeon', type: 'Specialty' },
    { text: 'Back pain', type: 'Condition' },
    { text: 'Annual physical', type: 'Condition' },
    { text: 'Teeth cleaning', type: 'Condition' },
    { text: 'Skin rash', type: 'Condition' },
    { text: 'Anxiety', type: 'Condition' },
    { text: 'Vision exam', type: 'Condition' },
    { text: 'Dr. Sarah Chen', type: 'Doctor' },
    { text: 'Dr. Michael Torres', type: 'Doctor' },
    { text: 'Dr. Emily Park', type: 'Doctor' },
  ];

  let activeSuggestionIndex = -1;

  function renderSuggestions(query) {
    const lowerQuery = query.toLowerCase().trim();
    if (!lowerQuery) {
      searchSuggestions.hidden = true;
      searchInput.setAttribute('aria-expanded', 'false');
      return;
    }

    const filtered = suggestionsData.filter(function (item) {
      return item.text.toLowerCase().includes(lowerQuery);
    });

    if (filtered.length === 0) {
      searchSuggestions.hidden = true;
      searchInput.setAttribute('aria-expanded', 'false');
      return;
    }

    searchSuggestions.innerHTML = filtered
      .slice(0, 6)
      .map(function (item, index) {
        const highlighted = item.text.replace(
          new RegExp('(' + escapeRegex(lowerQuery) + ')', 'gi'),
          '<strong>$1</strong>'
        );
        return (
          '<li role="option" data-index="' +
          index +
          '" tabindex="-1">' +
          highlighted +
          ' <span style="color:#98A2B3;font-size:12px;margin-left:4px;">' +
          item.type +
          '</span></li>'
        );
      })
      .join('');

    searchSuggestions.hidden = false;
    searchInput.setAttribute('aria-expanded', 'true');
    activeSuggestionIndex = -1;
  }

  function escapeRegex(string) {
    return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  if (searchInput && searchSuggestions) {
    searchInput.addEventListener('input', function () {
      renderSuggestions(searchInput.value);
    });

    searchInput.addEventListener('keydown', function (e) {
      const items = searchSuggestions.querySelectorAll('li');
      if (items.length === 0) return;

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        activeSuggestionIndex = Math.min(activeSuggestionIndex + 1, items.length - 1);
        updateActiveSuggestion(items);
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        activeSuggestionIndex = Math.max(activeSuggestionIndex - 1, -1);
        updateActiveSuggestion(items);
      } else if (e.key === 'Enter') {
        if (activeSuggestionIndex >= 0 && items[activeSuggestionIndex]) {
          e.preventDefault();
          const text = items[activeSuggestionIndex].childNodes[0].textContent.trim();
          searchInput.value = text;
          searchSuggestions.hidden = true;
          searchInput.setAttribute('aria-expanded', 'false');
        }
      } else if (e.key === 'Escape') {
        searchSuggestions.hidden = true;
        searchInput.setAttribute('aria-expanded', 'false');
        activeSuggestionIndex = -1;
      }
    });

    searchSuggestions.addEventListener('click', function (e) {
      const li = e.target.closest('li');
      if (li) {
        const text = li.childNodes[0].textContent.trim();
        searchInput.value = text;
        searchSuggestions.hidden = true;
        searchInput.setAttribute('aria-expanded', 'false');
        searchInput.focus();
      }
    });

    // Close suggestions when clicking outside
    document.addEventListener('click', function (e) {
      if (!searchInput.contains(e.target) && !searchSuggestions.contains(e.target)) {
        searchSuggestions.hidden = true;
        searchInput.setAttribute('aria-expanded', 'false');
        activeSuggestionIndex = -1;
      }
    });
  }

  function updateActiveSuggestion(items) {
    items.forEach(function (item, index) {
      if (index === activeSuggestionIndex) {
        item.setAttribute('aria-selected', 'true');
        item.scrollIntoView({ block: 'nearest' });
      } else {
        item.removeAttribute('aria-selected');
      }
    });
  }

  // ========================================
  // Insurance Dropdown
  // ========================================
  const insuranceInput = document.getElementById('insuranceInput');
  const insuranceSuggestions = document.getElementById('insuranceSuggestions');

  const insurancePlans = [
    'Aetna',
    'Blue Cross Blue Shield',
    'Cigna',
    'UnitedHealthcare',
    'Humana',
    'Kaiser Permanente',
    'Medicare',
    'Medicaid',
    'Oscar Health',
    'Anthem',
  ];

  let activeInsuranceIndex = -1;

  function renderInsuranceDropdown() {
    insuranceSuggestions.innerHTML = insurancePlans
      .map(function (plan, index) {
        return '<li role="option" data-index="' + index + '" tabindex="-1">' + plan + '</li>';
      })
      .join('');
    insuranceSuggestions.hidden = false;
    insuranceInput.setAttribute('aria-expanded', 'true');
    activeInsuranceIndex = -1;
  }

  if (insuranceInput && insuranceSuggestions) {
    insuranceInput.addEventListener('click', function () {
      if (insuranceSuggestions.hidden) {
        renderInsuranceDropdown();
      } else {
        insuranceSuggestions.hidden = true;
        insuranceInput.setAttribute('aria-expanded', 'false');
      }
    });

    insuranceInput.addEventListener('keydown', function (e) {
      const items = insuranceSuggestions.querySelectorAll('li');

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        if (insuranceSuggestions.hidden) {
          renderInsuranceDropdown();
          return;
        }
        activeInsuranceIndex = Math.min(activeInsuranceIndex + 1, items.length - 1);
        updateActiveSuggestion(items);
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        activeInsuranceIndex = Math.max(activeInsuranceIndex - 1, -1);
        updateActiveSuggestion(items);
      } else if (e.key === 'Enter') {
        if (activeInsuranceIndex >= 0 && items[activeInsuranceIndex]) {
          e.preventDefault();
          insuranceInput.value = items[activeInsuranceIndex].textContent.trim();
          insuranceSuggestions.hidden = true;
          insuranceInput.setAttribute('aria-expanded', 'false');
        }
      } else if (e.key === 'Escape') {
        insuranceSuggestions.hidden = true;
        insuranceInput.setAttribute('aria-expanded', 'false');
        activeInsuranceIndex = -1;
      }
    });

    insuranceSuggestions.addEventListener('click', function (e) {
      const li = e.target.closest('li');
      if (li) {
        insuranceInput.value = li.textContent.trim();
        insuranceSuggestions.hidden = true;
        insuranceInput.setAttribute('aria-expanded', 'false');
        insuranceInput.focus();
      }
    });

    document.addEventListener('click', function (e) {
      if (!insuranceInput.contains(e.target) && !insuranceSuggestions.contains(e.target)) {
        insuranceSuggestions.hidden = true;
        insuranceInput.setAttribute('aria-expanded', 'false');
        activeInsuranceIndex = -1;
      }
    });
  }

  // ========================================
  // Location Detect
  // ========================================
  const locationDetect = document.getElementById('locationDetect');
  const locationInput = document.getElementById('locationInput');

  if (locationDetect && locationInput) {
    locationDetect.addEventListener('click', function () {
      if (navigator.geolocation) {
        locationDetect.style.color = 'var(--color-primary)';
        navigator.geolocation.getCurrentPosition(
          function (position) {
            // In a real app, reverse geocode here
            locationInput.value = 'Current Location';
            locationDetect.style.color = '';
          },
          function () {
            locationInput.value = '';
            locationDetect.style.color = '';
            alert('Unable to retrieve your location. Please enter it manually.');
          }
        );
      } else {
        alert('Geolocation is not supported by your browser.');
      }
    });
  }

  // ========================================
  // Specialty Cards
  // ========================================
  const specialtyCards = document.querySelectorAll('.specialty-card');

  specialtyCards.forEach(function (card) {
    card.addEventListener('click', function (e) {
      e.preventDefault();
      const specialty = card.getAttribute('data-specialty');
      if (specialty && searchInput) {
        searchInput.value = specialty;
        searchInput.focus();
        // Scroll to search
        document.getElementById('search').scrollIntoView({ behavior: 'smooth' });
      }
    });
  });

  // ========================================
  // Search Form Submit
  // ========================================
  const searchForm = document.getElementById('searchForm');

  if (searchForm) {
    searchForm.addEventListener('submit', function (e) {
      e.preventDefault();
      const q = searchInput ? searchInput.value.trim() : '';
      const loc = locationInput ? locationInput.value.trim() : '';
      const ins = insuranceInput ? insuranceInput.value.trim() : '';

      if (!q && !loc) {
        searchInput.focus();
        return;
      }

      // Build query params
      const params = new URLSearchParams();
      if (q) params.set('q', q);
      if (loc) params.set('location', loc);
      if (ins) params.set('insurance', ins);

      // In a real app, navigate to search results
      alert('Searching for: ' + (q || 'all doctors') + (loc ? ' in ' + loc : '') + (ins ? ' with ' + ins : ''));
    });
  }

  // ========================================
  // Smooth scroll for anchor links
  // ========================================
  document.querySelectorAll('a[href^="#"]').forEach(function (anchor) {
    anchor.addEventListener('click', function (e) {
      const href = anchor.getAttribute('href');
      if (href === '#') return;
      const target = document.querySelector(href);
      if (target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    });
  });
})();
